28: const PERKS=[{id:'legacy',name:'Toprak Mirası',icon:'🌳',desc:'Kalıcı olarak +%15 satış geliri',cost:1,max:10},{id:'swift',name:'Rüzgârın Ritmi',icon:'💨',desc:'Kalıcı olarak %10 hızlı büyüme',cost:1,max:8},{id:'fortune',name:'Bereketli Başlangıç',icon:'🎁',desc:'Sıfırlamada daha çok başlangıç parası',cost:2,max:5},{id:'seedling',name:'Ata Tohumu',icon:'🌱',desc:'Yeni döngüye +3 havuç tohumu',cost:2,max:5}];
