33: function save(){S.last=Date.now();localStorage.setItem('minikHasatSave',JSON.stringify(S))}
34: function multiplier(){return (1+level('greenThumb')*.25)*(1+perkLevel('legacy')*.15)}
35: function growMultiplier(){return (1-level('quickHands')*.12)*(1-perkLevel('swift')*.10)}
36: function cropDef(id){return CROPS.find(c=>c.id===id)}
37: function cost(up){return Math.floor(up.base*Math.pow(1.65,level(up.id)))}
38: function notify(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
39: function unlocked(c){if(c.id==='carrot'||c.id==='wheat')return true;if(c.id==='tomato'||c.id==='corn')return level('greenThumb')>=1||S.sold>=18;if(c.id==='strawberry')return S.sold>=70||level('greenThumb')>=3;return false}
40: function plant(plot,crop){if(plot.crop||!crop||!S.seeds[crop.id])return false;plot.crop=crop.id;plot.planted=Date.now();plot.ready=false;S.seeds[crop.id]--;return true}
41: function elapsed(plot){return plot.crop?((Date.now()-plot.planted)/1000):0}
42: function isReady(plot){if(!plot.crop)return false;return plot.ready||elapsed(plot)>=cropDef(plot.crop).grow*growMultiplier()}
